import { sql } from 'drizzle-orm';
import { char, customType, integer, jsonb, timestamp, uuid } from 'drizzle-orm/pg-core';
import type { Translations } from '@tix/shared';

/**
 * Primary key: UUIDv7 generated by PostgreSQL 18 (`uuidv7()`), time-ordered for
 * B-tree locality on high insert volumes (orders, tickets, check-in logs).
 */
export const id = () =>
  uuid('id')
    .primaryKey()
    .default(sql`uuidv7()`);

export const tstz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

export const createdAt = () => tstz('created_at').notNull().defaultNow();

export const updatedAt = () =>
  tstz('updated_at')
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

export const timestamps = () => ({ createdAt: createdAt(), updatedAt: updatedAt() });

/** Money in integer minor units (cents). */
export const cents = (name: string) => integer(name);

/** Percent values in basis points (1900 = 19.00 %). */
export const basisPoints = (name: string) => integer(name);

/** ISO 4217 currency code. */
export const currency = (name = 'currency') => char(name, { length: 3 });

/** Content translations `{ "<locale>": { "<field>": "<text>" } }` (base text lives in the entity's columns). */
export const translationsColumn = () =>
  jsonb('translations')
    .$type<Translations>()
    .notNull()
    .default(sql`'{}'::jsonb`);

/** PostgreSQL `xid8` (64-bit transaction id); values travel as decimal strings. */
export const xid8 = customType<{ data: string; driverData: string }>({
  dataType: () => 'xid8',
});
